// DATA STRUCTURES (copied from fem.sio)
// ============================================================================

struct FEMesh1D {
    nodes: [f64; 256],
    n_nodes: i32,
    elements: [i32; 512],
    n_elem: i32,
    nodes_per_elem: i32
}

struct FEMesh2D {
    nodes_x: [f64; 256],
    nodes_y: [f64; 256],
    n_nodes: i32,
    elements: [i32; 1536],
    n_elem: i32,
    nodes_per_elem: i32
}

struct FESystem {
    K: [f64; 4096],
    M: [f64; 4096],
    rhs: [f64; 256],
    solution: [f64; 256],
    n_dof: i32
}

struct FEResult {
