fn test_1d_stiffness_symmetry() -> bool with Mut, Div, Panic {
    let tol = 1.0e-6
    let EA = 200.0e3
    let x1 = 0.0
    let x2 = 2.5

    var ke: [f64; 4] = [0.0; 4]
    fem_1d_stiffness(x1, x2, EA, &!ke)

    // ke is 2x2 row-major: ke[1] = K(0,1), ke[2] = K(1,0)
    let diff = fe_abs(ke[1] - ke[2])
    if diff > tol { return false }
    true
}

