// TEST 2: 1D stiffness trace -- ke[0][0] + ke[1][1] = 2*EA/L
// ============================================================================

fn test_1d_stiffness_trace() -> bool with Mut, Div, Panic {
    let tol = 1.0e-6
    let EA = 150.0e3
    let x1 = 1.0
    let x2 = 4.0
    let L = fe_abs(x2 - x1)

    var ke: [f64; 4] = [0.0; 4]
    fem_1d_stiffness(x1, x2, EA, &!ke)

    let trace = ke[0] + ke[3]
    let expected = 2.0 * EA / L
    let diff = fe_abs(trace - expected)
    if diff > tol { return false }
    true
}

