fn test_tri_shape_at_vertices() -> bool with Mut, Div, Panic {
    let tol = 1.0e-6
    // Triangle: (0,0), (1,0), (0,1)
    let x1 = 0.0
    let y1 = 0.0
    let x2 = 1.0
    let y2 = 0.0
    let x3 = 0.0
    let y3 = 1.0

    // Evaluate at vertex 1: (0,0) -> N = (1, 0, 0)
    var N: [f64; 3] = [0.0; 3]
    fem_tri_shape(x1, y1, x2, y2, x3, y3, x1, y1, &!N)
    if fe_abs(N[0] - 1.0) > tol { return false }
    if fe_abs(N[1]) > tol { return false }
    if fe_abs(N[2]) > tol { return false }

    // Evaluate at vertex 2: (1,0) -> N = (0, 1, 0)
    fem_tri_shape(x1, y1, x2, y2, x3, y3, x2, y2, &!N)
    if fe_abs(N[0]) > tol { return false }
    if fe_abs(N[1] - 1.0) > tol { return false }
    if fe_abs(N[2]) > tol { return false }

    // Evaluate at vertex 3: (0,1) -> N = (0, 0, 1)
    fem_tri_shape(x1, y1, x2, y2, x3, y3, x3, y3, &!N)
    if fe_abs(N[0]) > tol { return false }
    if fe_abs(N[1]) > tol { return false }
    if fe_abs(N[2] - 1.0) > tol { return false }

    true
}

