// ============================================================================
// TEST 8: 1D bar exact solution
//
// Fixed-free bar under uniform distributed load q.
//   - Domain [0, L], fixed at x=0, free at x=L
//   - EA = const, load q per unit length
//   - Analytical: u(x) = q*x*(2L - x) / (2*EA)
//   - With penalty BC at node 0 (u=0), compare FE solution to analytical
//     at the free end: u(L) = q*L^2 / (2*EA)
// ============================================================================

fn test_1d_bar_exact() -> bool with Mut, Div, Panic {
    let tol = 1.0e-6
    let L = 10.0
    let EA = 1.0e5
    let q = 100.0
    let n_elem = 4

    // Create mesh
    var mesh: FEMesh1D = FEMesh1D {
        nodes: [0.0; 256], n_nodes: 0,
        elements: [0; 512], n_elem: 0, nodes_per_elem: 2
    }
    fem_mesh_1d_uniform(0.0, L, n_elem, &!mesh)

    let n = mesh.n_nodes

    // Assemble K and F
    var K: [f64; 4096] = [0.0; 4096]
    var F: [f64; 256] = [0.0; 256]
    fem_assemble_stiffness_1d(&mesh, EA, &!K)
    fem_assemble_load_1d(&mesh, q, &!F)

    // Apply Dirichlet BC: u(0) = 0 via penalty
    fem_apply_dirichlet_penalty(&!K, &!F, n, 0, 0.0)

    // Solve
    var u: [f64; 256] = [0.0; 256]
    fem_solve_direct(&K, &F, n, &!u)

    // Compare each node to analytical solution: u(x) = q*x*(2L - x) / (2*EA)
    var ok = true
    var i = 0
    while i < n {
        let x = mesh.nodes[i]
        let u_exact = q * x * (2.0 * L - x) / (2.0 * EA)
        let diff = fe_abs(u[i] - u_exact)
        // Use relative tolerance for non-zero values
        if fe_abs(u_exact) > 1.0e-12 {
            if diff / fe_abs(u_exact) > tol { ok = false }
        } else {
            if diff > tol { ok = false }
        }
        i = i + 1
    }

    ok
}

// ============================================================================
// TEST 9: 2D patch test
//
// A single-element (or 2-element) patch under uniform strain should
// reproduce the exact stress. We set up a 1x1 square meshed into 2 CST
// triangles with prescribed displacements corresponding to a uniform
// strain exx = 0.001 (pure x-extension): u_x = 0.001 * x, u_y = 0.
// The stress should be sigma_xx = E/(1-nu^2) * exx + E*nu/(1-nu^2) * 0
// and sigma_yy = E*nu/(1-nu^2) * exx.
// ============================================================================

fn test_2d_patch_test() -> bool with Mut, Div, Panic {
    let tol = 1.0e-4
    let E = 1.0e6
    let nu = 0.25
    let thickness = 1.0
    let exx = 0.001

    // Create 1x1 mesh (2 elements, 4 nodes)
    var mesh: FEMesh2D = FEMesh2D {
        nodes_x: [0.0; 256], nodes_y: [0.0; 256], n_nodes: 0,
        elements: [0; 1536], n_elem: 0, nodes_per_elem: 3
    }
    fem_mesh_2d_rect(0.0, 0.0, 1.0, 1.0, 1, 1, &!mesh)

    // Constitutive matrix
    var D: [f64; 9] = [0.0; 9]
    fem_plane_stress(E, nu, &!D)

    // Prescribed displacement: u_x = exx * x, u_y = 0
    // Nodes from fem_mesh_2d_rect(0,0,1,1,1,1):
    //   node 0 = (0,0), node 1 = (1,0), node 2 = (0,1), node 3 = (1,1)
    // DOF: [u_x0, u_y0, u_x1, u_y1, u_x2, u_y2, u_x3, u_y3]
    var u_disp: [f64; 256] = [0.0; 256]
    var nd = 0
    while nd < mesh.n_nodes {
        u_disp[2 * nd] = exx * mesh.nodes_x[nd]
        u_disp[2 * nd + 1] = 0.0
        nd = nd + 1
    }

    // Expected stress
    let c = E / (1.0 - nu * nu)
    let sxx_expected = c * exx
    let syy_expected = c * nu * exx
    let sxy_expected = 0.0

    // Check stress in each element
    var ok = true
    var e = 0
    while e < mesh.n_elem {
        var sr: StressResult = StressResult {
            sxx: 0.0, syy: 0.0, sxy: 0.0, von_mises: 0.0
        }
        fem_stress_at_centroid(&mesh, &u_disp, &D, e, &!sr)

        if fe_abs(sr.sxx - sxx_expected) > tol * fe_abs(sxx_expected) { ok = false }
        if fe_abs(sr.syy - syy_expected) > tol * fe_abs(syy_expected) { ok = false }
        if fe_abs(sr.sxy - sxy_expected) > tol { ok = false }

        e = e + 1
    }

    ok
}

// ============================================================================
// TEST 10: CG solver matches direct solver
//
// Build a small 1D problem (3 elements, 4 nodes), apply Dirichlet at node 0,
// solve with both direct and CG, compare solutions.
// ============================================================================

fn test_cg_matches_direct() -> bool with Mut, Div, Panic {
    // Use a well-conditioned 4x4 tridiagonal SPD system:
    //   K = [[2,-1,0,0],[-1,2,-1,0],[0,-1,2,-1],[0,0,-1,2]]
    //   F = [1,1,1,1]
    // Condition number ~16 → CG converges in ≤4 iterations (exact)
    let tol = 1.0e-8
    let n = 4

    var K: [f64; 4096] = [0.0; 4096]
    var F: [f64; 256] = [0.0; 256]

    // Build tridiagonal K
    var i = 0
    while i < n {
        K[i * n + i] = 2.0
        if i > 0 { K[i * n + (i - 1)] = -1.0 }
        if i < n - 1 { K[i * n + (i + 1)] = -1.0 }
        F[i] = 1.0
        i = i + 1
    }

    // Direct solve
    var u_direct: [f64; 256] = [0.0; 256]
    fem_solve_direct(&K, &F, n, &!u_direct)

    // CG solve
    var u_cg: [f64; 256] = [0.0; 256]
    let cg_converged = fem_solve_cg(&K, &F, n, &!u_cg, 100, 1.0e-12)

    if !cg_converged { return false }

    // Compare solutions
    var ok = true
    i = 0
    while i < n {
        let diff = fe_abs(u_direct[i] - u_cg[i])
        if fe_abs(u_direct[i]) > 1.0e-12 {
            if diff / fe_abs(u_direct[i]) > tol { ok = false }
        } else {
            if diff > tol { ok = false }
        }
        i = i + 1
    }
    ok
}

// ============================================================================
// TEST 11: Dirichlet penalty BC makes K[dof][dof] >> other entries
// ============================================================================

fn test_dirichlet_penalty() -> bool with Mut, Div, Panic {
    let n = 4
    // Build a small stiffness matrix (identity-like for simplicity)
    var K: [f64; 4096] = [0.0; 4096]
    var F: [f64; 256] = [0.0; 256]
    var i = 0
    while i < n {
        K[i * n + i] = 1.0e3
        F[i] = 100.0
        i = i + 1
    }

    // Apply Dirichlet at DOF 1 with value 0.0
    fem_apply_dirichlet_penalty(&!K, &!F, n, 1, 0.0)

    // K[1][1] should now be 1e3 + 1e20 ~ 1e20
    let diag = K[1 * n + 1]

    // Check that the diagonal is orders of magnitude larger than off-diags
    var ok = true
    var j = 0
    while j < n {
        if j != 1 {
            let off = fe_abs(K[1 * n + j])
            // The penalty-augmented diagonal should dominate
            if off > 0.0 {
                if diag / off < 1.0e10 { ok = false }
            }
        }
        j = j + 1
    }

    // Also check the diagonal is at least 1e15 (penalty = 1e20)
    if diag < 1.0e15 { ok = false }

    ok
}

// ============================================================================
// TEST 12: 1D uniform mesh has correct number of nodes and elements
// ============================================================================

fn test_mesh_1d_counts() -> bool with Mut, Div, Panic {
    let n_elem = 8

    var mesh: FEMesh1D = FEMesh1D {
        nodes: [0.0; 256], n_nodes: 0,
        elements: [0; 512], n_elem: 0, nodes_per_elem: 2
    }
    fem_mesh_1d_uniform(0.0, 10.0, n_elem, &!mesh)

    // n_nodes should be n_elem + 1 = 9
    if mesh.n_nodes != n_elem + 1 { return false }

    // n_elem should be 8
    if mesh.n_elem != n_elem { return false }

    // nodes_per_elem should be 2
    if mesh.nodes_per_elem != 2 { return false }

    // Check first and last node positions
    let tol = 1.0e-6
    if fe_abs(mesh.nodes[0] - 0.0) > tol { return false }
    if fe_abs(mesh.nodes[n_elem] - 10.0) > tol { return false }

    // Check uniform spacing: h = 10/8 = 1.25
    let h = 10.0 / (n_elem as f64)
    var i = 0
    while i < mesh.n_nodes {
        let expected = (i as f64) * h
        if fe_abs(mesh.nodes[i] - expected) > tol { return false }
        i = i + 1
    }

    true
}

